import{c as e,Q as r,j as a,m as s}from"./chunks/framework.dywCjXaF.js";const p=JSON.parse('{"title":"The 6 Report Sections","description":"","frontmatter":{},"headers":[],"relativePath":"report-guide.md","filePath":"report-guide.md"}'),i={name:"report-guide.md"};function o(n,t,d,l,h,u){return r(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="the-6-report-sections" tabindex="-1">The 6 Report Sections <a class="header-anchor" href="#the-6-report-sections" aria-label="Permalink to &quot;The 6 Report Sections&quot;">​</a></h1><p>Every Sarva-Varadi report is a single <code>index.html</code> — a sidebar SPA with six tabs. Open it in any browser, no server needed.</p><nav class="table-of-contents"><ul><li><a href="#_1-overview">1. Overview</a></li><li><a href="#_2-failures">2. Failures</a></li><li><a href="#_3-tests">3. Tests</a></li><li><a href="#_4-trends">4. Trends</a></li><li><a href="#_5-timeline">5. Timeline</a></li><li><a href="#_6-run-history">6. Run History</a></li><li><a href="#sidebar-theme">Sidebar &amp; theme</a></li></ul></nav><hr><h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The default landing tab when you open the report.</p><table tabindex="0"><thead><tr><th>Widget</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Stat cards</strong></td><td>Total / Passed / Failed / Flaky / Skipped counts with trend arrows vs. previous run</td></tr><tr><td><strong>Pass rate donut</strong></td><td>Visual pass rate with centre count</td></tr><tr><td><strong>Health Pulse</strong></td><td>Rolling pass rate sparkline across the last N runs — rising = improving, flat at 100% = stable</td></tr><tr><td><strong>Needs Attention</strong></td><td>Auto-shown strip when failures exceed 10% or flaky count is high</td></tr><tr><td><strong>New Tests</strong></td><td>Tests that appeared for the first time this run (hidden when empty)</td></tr><tr><td><strong>Absent Tests</strong></td><td>Tests present in the previous run but missing now (hidden when empty)</td></tr><tr><td><strong>Top Failing</strong></td><td>Ranked list of most frequently failing tests across history</td></tr><tr><td><strong>Top Flaky</strong></td><td>Ranked list of tests with highest flaky score</td></tr><tr><td><strong>Run metadata</strong></td><td>Timestamp, tool, framework, environment badge</td></tr></tbody></table><hr><h2 id="_2-failures" tabindex="-1">2. Failures <a class="header-anchor" href="#_2-failures" aria-label="Permalink to &quot;2. Failures&quot;">​</a></h2><p>Dedicated failures view for fast triage without scrolling through the full test list.</p><table tabindex="0"><thead><tr><th>Section</th><th>Content</th></tr></thead><tbody><tr><td><strong>Newly Failing</strong></td><td>Tests that passed last run but failed this run</td></tr><tr><td><strong>Recently Fixed</strong></td><td>Tests that failed last run but passed this run</td></tr><tr><td><strong>All Failures</strong></td><td>Every failed and flaky test ranked by severity label</td></tr></tbody></table><p>Severity levels: <code>critical</code> → <code>high</code> → <code>medium</code> → <code>low</code> → unlabelled.</p><hr><h2 id="_3-tests" tabindex="-1">3. Tests <a class="header-anchor" href="#_3-tests" aria-label="Permalink to &quot;3. Tests&quot;">​</a></h2><p>Full test list with filter, search, sort, and per-test detail.</p><p><strong>List features:</strong></p><ul><li>Filter by status (passed / failed / flaky / skipped / all)</li><li>Free-text search (matches test name)</li><li>Sort by name, duration, or status</li><li>CSV export button</li></ul><p><strong>Test detail drawer</strong> — click any test to open:</p><ul><li>Full step tree with collapsible nodes</li><li>BDD hierarchy: Feature → Scenario → Step (Cucumber)</li><li>HTTP sub-steps: method, URL, status, request/response (RestAssured)</li><li>WebDriver sub-steps (Selenium)</li><li>Error message + stack trace (collapsible)</li><li>Attachments: screenshots, videos, traces (embedded)</li><li>Per-test history chart: last 25 runs, colour-coded by outcome</li></ul><hr><h2 id="_4-trends" tabindex="-1">4. Trends <a class="header-anchor" href="#_4-trends" aria-label="Permalink to &quot;4. Trends&quot;">​</a></h2><p>Six ECharts charts across historical runs — oldest left, newest right.</p><table tabindex="0"><thead><tr><th>Chart</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Pass Rate Trend</strong></td><td>% passed per run with rolling average dashed line</td></tr><tr><td><strong>Failures &amp; Flakiness</strong></td><td>Failed + flaky counts per run (stacked bars)</td></tr><tr><td><strong>Failures by Severity</strong></td><td>Stacked bars split by severity label — only shown when <code>@severity</code> tags are present</td></tr><tr><td><strong>Test Count Over Time</strong></td><td>Stacked area: passed / failed / flaky / skipped per run</td></tr><tr><td><strong>Run Duration Trend</strong></td><td>Seconds per run with rolling average</td></tr><tr><td><strong>Top Failing Tests</strong></td><td>Horizontal bar chart ranked by failure count</td></tr><tr><td><strong>Top Flaky Tests</strong></td><td>Horizontal bar chart ranked by flakiness rate</td></tr></tbody></table><p>All charts share a <strong>run-count filter</strong> (Last 10 / 20 / 50 / All runs) at the top of the tab.</p><p>When a historical run is active (<a href="./run-history.html">Run History</a>), charts auto-center a window on the selected run and show a dashed marker at its position.</p><hr><h2 id="_5-timeline" tabindex="-1">5. Timeline <a class="header-anchor" href="#_5-timeline" aria-label="Permalink to &quot;5. Timeline&quot;">​</a></h2><p>Two charts about <em>when</em> things ran:</p><table tabindex="0"><thead><tr><th>Chart</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Run Cadence</strong></td><td>Bar chart of runs over time — spot gaps, clusters, CI frequency</td></tr><tr><td><strong>Execution Gantt</strong></td><td>Horizontal timeline of every test — start time, duration, and outcome colour-coded</td></tr></tbody></table><p>The Gantt is useful for identifying which tests take longest and whether parallelism is working as expected.</p><hr><h2 id="_6-run-history" tabindex="-1">6. Run History <a class="header-anchor" href="#_6-run-history" aria-label="Permalink to &quot;6. Run History&quot;">​</a></h2><p>→ <a href="./run-history.html">Detailed guide</a></p><p>Filterable table of every historical run. Click any row to re-render all charts — Overview, Failures, Tests, Trends, and Timeline — against that run. A viewing banner persists across all tabs while a historical run is active.</p><hr><h2 id="sidebar-theme" tabindex="-1">Sidebar &amp; theme <a class="header-anchor" href="#sidebar-theme" aria-label="Permalink to &quot;Sidebar &amp; theme&quot;">​</a></h2><p>The sidebar shows the six tabs. Each tab icon shows a badge with the count of relevant items (e.g. Failures tab shows failure count). The top-right toggle switches between <strong>dark</strong> and <strong>light</strong> theme. The setting is persisted in localStorage.</p>',37)])])}const g=e(i,[["render",o]]);export{p as __pageData,g as default};
